import{z as r,x as o,o as e,c as d,q as t,j as i,D as a,d as B,s as n,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"合成评测集的构造","description":"","frontmatter":{"title":"合成评测集的构造","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-eval-sets.md","filePath":"llm/synthetic-eval-sets.md","lastUpdated":1791413859000}'),h={name:"llm/synthetic-eval-sets.md"};function m(D,E,p,C,c,F){const l=o("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="合成评测集的构造" tabindex="-1">合成评测集的构造 <a class="header-anchor" href="#合成评测集的构造" aria-label="Permalink to &quot;合成评测集的构造&quot;">​</a></h1><div class="epigraph"><p>用合成机器造评测，风险从「训练学坏」换成「评测自欺」：分数可以完全真实，结论可以完全错误。</p><footer>—— 据 Kiela 等 Dynabench；White 等 LiveBench 整理</footer></div><p><a href="/llm/synthetic-small-model-mix">上一课</a>把训练配比定版；本课把同一套合成机器转向评测集。训练-评测污染的检测已有专课：<a href="/llm/decontamination-pipeline">评测去污染流水线</a>与<a href="/llm/eval-contamination">训练-评测污染检测</a>，LiveBench 类动态基准给过「月更新加客观评分」的口径（<a href="/llm/livebench">LiveBench</a>）。本课写更上游的问题：当你决定自己合成一个评测集时，构造本身要守什么纪律。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合成评测有三种做法，缺口各不相同。模板加参数采样：从程序模板生成题与标准答案，真值由生成器定义，最干净也最危险——它测的是「模板正则性」还是「能力」，取决于模板藏得多深。教师出题加程序验证：题源开放、真值可靠，但与训练集同源的风险最高——教师出的题天然长成它能解的样子，模型若在同类题上被密集训练，分数上涨与能力无关。真实种子改写：把真实题换数字换情境，效度最好，污染检测却更难——表面改了，解法结构没改。三类共同的死穴是自欺：评测的生产者与训练数据的生产者是同一个团队、同一批教师、有时是同一份模板库。<span class="marginnote">直觉类比：让教师给自己出考卷，题目会天然长成它擅长的样子——就像老师偏爱出自己会讲的题型。再用同类题密集训练，等于考前把出题人的草稿纸刷了十遍：分数暴涨，「能力」没动。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四条纪律。生成器隔离：训练与评测的模板库、种子、教师版本全部物理分开，隔离审计写进发布流程——这是「训练测试分离」在合成时代的重写，违反它的高分一律无效。效度三问：每道题入库前过「它测什么」（对应能力清单的哪一格）、「答对说明什么」（排除捷径路径）、「怎么防背题」（参数空间够不够大）。稳定性预算：题量与参数采样决定的置信区间要写进报告，单点分差小于区间不得下结论。真实锚定：合成评测集只做高频回归，方向性结论必须在一小片真实题上复核；换题周期要短于模板被拟合的速度。</p>',7)),(e(),i(s,null,{default:a(()=>[n(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN_T%5B%22%E8%AF%84%E6%B5%8B%E7%94%9F%E6%88%90%E5%99%A8%EF%BC%9A%E7%8B%AC%E7%AB%8B%E6%A8%A1%E6%9D%BF%E4%B8%8E%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20Q%5B%22%E7%94%9F%E6%88%90%E5%80%99%E9%80%89%E9%A2%98%22%5D%0A%20%20Q%20--%3E%20VALID%7B%22%E6%95%88%E5%BA%A6%E4%B8%89%E9%97%AE%EF%BC%9A%E6%B5%8B%E4%BB%80%E4%B9%88%2F%E8%AF%B4%E6%98%8E%E4%BB%80%E4%B9%88%2F%E9%98%B2%E8%83%8C%E9%A2%98%22%7D%0A%20%20VALID%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%E6%88%96%E9%87%8D%E9%80%A0%22%5D%0A%20%20VALID%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20FREEZE%5B%22%E5%86%BB%E7%BB%93%E5%B9%B6%E7%89%88%E6%9C%AC%E5%8C%96%22%5D%0A%20%20FREEZE%20--%3E%20RUN%5B%22%E9%AB%98%E9%A2%91%E5%9B%9E%E5%BD%92%E8%AF%84%E6%B5%8B%22%5D%0A%20%20RUN%20--%3E%20REAL%7B%22%E7%9C%9F%E5%AE%9E%E9%94%9A%E7%82%B9%E5%A4%8D%E6%A0%B8%22%7D%0A%20%20REAL%20--%3E%7C%E6%96%B9%E5%90%91%E4%B8%80%E8%87%B4%7C%20OK%5B%22%E7%BB%93%E8%AE%BA%E6%9C%89%E6%95%88%22%5D%0A%20%20REAL%20--%3E%7C%E8%83%8C%E7%A6%BB%7C%20ALARM%5B%22%E5%9B%9E%E6%9F%A5%EF%BC%9A%E6%B3%84%E6%BC%8F%E6%88%96%E6%A8%A1%E6%9D%BF%E6%8B%9F%E5%90%88%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"合成评测自欺的机制是优化压力对生成器捷径的利用：任何模板都有正则性——参数分布、句式骨架、答案形态——模型不需要学会任务，只需要学会「这类生成器会出什么」。参数空间放大与情境改写抬高的是记忆成本而不是学习成本，恰好是当前大模型最充裕的资源；所以防背题不能靠「题面变体够多」，要靠换题周期与生成器隔离把结构差立住。动态更新与静态冻结是一对张力：LiveBench 用月更新对抗污染，内部评测集的更新受制于版本管理与可比性——工程折衷是双轨：冻结集保证可比，滚动集保证新鲜，结论以两轨一致为准。合成评测集同样要过污染扫描与许可检查：它是数据，不是法外之地。",-1)),(e(),i(s,null,{default:a(()=>[n(l,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%A8%A1%E6%9D%BF%E8%87%AA%E5%B8%A6%E6%AD%A3%E5%88%99%E6%80%A7%3A%20%E5%8F%82%E6%95%B0%E5%88%86%E5%B8%83%2F%E5%8F%A5%E5%BC%8F%2F%E7%AD%94%E6%A1%88%E5%BD%A2%E6%80%81%22%5D%20--%3E%20A%5B%22%E8%B7%AF%E5%BE%84%E4%B8%80%3A%20%E7%9C%9F%E7%9A%84%E5%AD%A6%E4%BC%9A%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20T%20--%3E%20B%5B%22%E8%B7%AF%E5%BE%84%E4%BA%8C%3A%20%E5%AD%A6%E4%BC%9A%E8%BF%99%E7%B1%BB%E7%94%9F%E6%88%90%E5%99%A8%E4%BC%9A%E5%87%BA%E4%BB%80%E4%B9%88%22%5D%0A%20%20B%20--%3E%20M%5B%22%E5%8F%82%E6%95%B0%E7%A9%BA%E9%97%B4%E5%B0%8F%2C%20%E8%AE%B0%E5%BF%86%E6%88%90%E6%9C%AC%E6%9E%81%E4%BD%8E%22%5D%0A%20%20M%20--%3E%20H%5B%22%E8%AF%84%E6%B5%8B%E5%88%86%E5%A4%A7%E6%B6%A8%2C%20%E7%9C%9F%E5%AE%9E%E4%BB%BB%E5%8A%A1%E6%B2%A1%E5%8A%A8%22%5D%0A%20%20A%20--%3E%20R%5B%22%E5%8F%AA%E6%9C%89%E7%9C%9F%E5%AE%9E%E9%94%9A%E7%82%B9%E5%A4%8D%E6%A0%B8%E8%83%BD%E5%8C%BA%E5%88%86%E4%B8%A4%E6%9D%A1%E8%B7%AF%22%5D%0A%20%20H%20--%3E%20R%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">数字实例：模板「计算 \\(a\\times b+c\\)」若三个参数各只取 10 个值，参数空间只有 1000 道题，把答案表背下来的成本极低；把每个参数扩到 500 个值、再套不同情境，同样的「题型」参数空间变成上亿——防背题靠的是这个，不是换措辞。</span></p><p><span class="marginnote">评测集与训练集共用同一教师与同一模板库时，可以出现「模型分涨了十点、真实题一分没涨」的完全虚假增益。把生成器隔离做成 CI 检查项：任何评测集构建脚本引用了训练侧模板或种子，构建直接失败。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>合成评测的效度上限是能力清单的完备性：清单里没有的能力，合成再精也测不到，清单本身要靠真实基准定期校。程序化模板适合有形式结构的域（数学、代码、受控抽取），开放域的「好回答」无法模板化，合成评测在这些域退化为裁判打分，回归质量受裁判漂移约束。换题周期短有成本：历史可比性断裂，趋势分析要靠锚题子集（跨版本固定的题）续接。最后，评测集的规模与方差纪律沿用评测方法课的口径：合成不豁免统计。<span class="marginnote">常见误区：初学者容易把「换题周期越短越好」当绝对真理。频繁换题会打断历史可比性——这季度分和上季度分不再是同一把尺。工程折衷是留一小撮「锚题」跨版本固定，用它们续接趋势，其余题滚动更新。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三种做法：模板采样最干净最险，教师出题防同源，真实改写效度最好。</li><li>生成器隔离是训练测试分离的重写：模板、种子、教师版本物理分开。</li><li>效度三问入库；题量置信区间写进报告。</li><li>双轨：冻结集可比，滚动集新鲜，结论以一致为准。</li><li>方向性结论必须过真实锚点复核。</li><li>出处：Kiela 等 Dynabench 2021；White 等 LiveBench 2025；本站去污染两课。</li></ul>',6))])}const u=r(h,[["render",m]]);export{f as __pageData,u as default};
